-- The dental team (shown on the About page and each doctor's own page), managed in the admin panel → Doctors.
-- Seeded with the profiles and photos supplied by the clinic. Dr. S. Vishwas (the main dentist) is not in this table.
CREATE TABLE IF NOT EXISTS doctors (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  slug          VARCHAR(120) NOT NULL,
  name          VARCHAR(120) NOT NULL,
  title         VARCHAR(80)  NULL,
  qualification VARCHAR(200) NULL,
  experience    VARCHAR(160) NULL,
  headline      VARCHAR(200) NULL,
  photo         VARCHAR(255) NULL,
  bio           TEXT NULL,
  profile       TEXT NULL,
  is_active     TINYINT(1) NOT NULL DEFAULT 1,
  sort_order    SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_doctors_slug (slug),
  KEY idx_doctors_active (is_active, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- INSERT IGNORE: a doctor already added (same web address) is left exactly as the clinic edited it.
INSERT IGNORE INTO doctors (slug, name, title, qualification, experience, headline, photo, bio, profile, sort_order) VALUES
  ('dr-madhukiran', 'Dr. Madhukiran', 'Endodontist', 'Specialist in Endodontics', '23 Years of Clinical Experience', NULL, '/photos/doctors/dr-madhukiran.jpg', 'An experienced dental professional with 23 years of clinical experience, specialising in Endodontics and dedicated to preserving natural teeth through advanced dental care.\n\nAssociated with Srinivasa Dental Clinic, BTM, Bangalore, the doctor focuses on accurate diagnosis, effective treatment planning and patient-friendly dental care.\n\nWith extensive clinical experience and a commitment to quality, the aim is to provide comfortable, reliable and personalised dental treatment while helping patients maintain healthy smiles.', '## Area of Expertise\n- Root Canal Treatment (RCT)\n- Advanced Endodontic Procedures\n- Tooth Preservation\n- Management of Dental Pulp Infections\n- Restorative Dental Care', 1),
  ('dr-darshan-b-mundinamane', 'Dr. Darshan B Mundinamane', 'Periodontist & Implantologist', 'MDS, Periodontics', '19 yrs (Practicing Periodontology and Implantology Since 2007)', NULL, '/photos/doctors/dr-darshan-b-mundinamane.jpg', NULL, '## Areas of Interest\n- Implantology\n- Immunology\n- Alternative Medicine\n\n## Proficient in\n- Management of Periodontitis\n- Implant Surgery & Maintenance\n- Root Coverage procedures\n- Mucogingival Procedures\n\n## Scope of Service\n- Periodontal Flap Surgeries and maintenance\n- Root coverage/esthetic gum surgeries\n- Dental Implant Placement and maintenance\n- Advanced bone and soft tissue augmentation surgeries for Dental Implants', 2),
  ('dr-anitha', 'Dr. Anitha', 'Pediatric & Preventive Dentistry', 'MDS, Pediatric and Preventive Dentistry', 'Associate Professor, Bangalore Institute of Dental Sciences', NULL, '/photos/doctors/dr-anitha.jpg', NULL, '## Educational Qualifications\n- Bachelor of Dental Surgery (BDS) – Manipal College of Dental Sciences (MCODS), Mangalore.\n- Batch of 1989.\n- Completed dentistry in 1994.\n\n## Professional Experience\nCurrently working as an Associate Professor in the Department of Pediatric and Preventive Dentistry at Bangalore Institute of Dental Sciences.', 3),
  ('dr-hemavathi', 'Dr. Hemavathi', 'General Dentist', 'BDS', '15 Years of Clinical Experience', NULL, '/photos/doctors/dr-hemavathi.jpg', 'Dr. Hemavathi is a qualified dental professional with 15 years of clinical experience in dentistry. She is dedicated to providing quality dental care, focusing on patients’ oral health, preventive care, and overall dental well-being.\n\nWith extensive clinical experience, she is committed to delivering comfortable, patient-friendly dental treatments and promoting healthy smiles.', NULL, 4),
  ('dr-srividhya-narasimhan', 'Dr. Srividhya Narasimhan', 'Orthodontist', 'BDS, MFDS RCPS (Glasgow), MDS (Orthodontics)', '30 Years of Experience | 13 Years in Orthodontics', NULL, '/photos/doctors/dr-srividhya-narasimhan.jpg', 'Dr. Srividhya Narasimhan is an experienced dental professional with 30 years of experience in general dentistry and 13 years of specialised experience in orthodontics.\n\nShe completed her Bachelor of Dental Surgery (BDS) in 1997, followed by MFDS from the Royal College of Physicians and Surgeons of Glasgow in 2007. She subsequently completed her Master of Dental Surgery (MDS) in Orthodontics between 2010 and 2013.\n\nWith extensive clinical experience and specialised orthodontic expertise, she is dedicated to providing quality dental care and helping patients achieve healthy, well-aligned smiles.', NULL, 5),
  ('dr-manoranjan-sj', 'Dr. Manoranjan SJ', 'Periodontist', 'BDS (1999), MDS (2007) – Periodontics', 'Faculty in AECS Maruthi Dental College for 15 yrs', NULL, '/photos/doctors/dr-manoranjan-sj.jpg', NULL, 'Qualification: BDS 1999, MDS 2007\nSpeciality: Periodontics\nOccupation: Faculty in AECS Maruthi Dental College for 15yrs\nDesignation: Professor, Dept of periodontics (Now Resigned)\nSpeciality treatment: Laser specialist for gum disease and intraoral soft tissue lesions\n\n## Area of interest\n- Flap Surgery\n- Laser assisted flap Surgery\n- Regenerative Periodontal Surgeries\n- Gums contouring for smile designing', 6),
  ('dr-nithin', 'Dr. Nithin', 'Oral & Maxillofacial Surgeon', 'BDS, MDS – Oral and Maxillofacial Surgeon (OMFS)', '2 Years of Clinical Experience', NULL, '/photos/doctors/dr-nithin.jpg', 'Dr. Nithin is a qualified Oral and Maxillofacial Surgeon with 2 years of clinical experience. Specialising in the diagnosis and surgical management of conditions affecting the mouth, jaws, face and associated structures, Dr. Nithin is committed to providing patient-focused care with precision, safety and attention to detail.', NULL, 7),
  ('dr-roshan', 'Dr. Roshan', 'Prosthodontist & Implantologist', 'MDS, PGDHHM', '24 Years of Professional Experience', 'Specialist in Prosthodontics and Implantology', '/photos/doctors/dr-roshan.jpg', 'Dr. Roshan is an experienced dental specialist with 24 years of professional experience in dentistry. He specialises in Prosthodontics and Implantology, focusing on restoring missing teeth, smile rehabilitation, and improving patients\' oral health and function through advanced dental treatments.\n\nHis extensive clinical experience and expertise enable him to provide comprehensive dental care with a focus on functional restoration and aesthetic outcomes.', NULL, 8),
  ('dr-karishma-kalal', 'Dr. Karishma Kalal', NULL, 'BDS', '10 Years of Clinical Experience', NULL, '/photos/doctors/dr-karishma-kalal.jpg', 'Dr. Karishma Kalal is a dedicated dental professional with a Bachelor of Dental Surgery (BDS) degree.\n\nShe has expertise in Root Canal Treatment, Dental Surgery, and Dental Implants, with a strong focus on providing quality dental care and ensuring patient comfort.\n\nKnown for her compassionate approach, clinical experience, and excellent patient understanding, Dr. Karishma believes in educating patients about their oral health and providing personalised treatment solutions.\n\nHer approach combines clinical expertise, gentle care, and a commitment to creating healthy, confident smiles.', NULL, 9),
  ('dr-g-anjum', 'Dr. G. Anjum', 'Dental Surgeon', NULL, NULL, NULL, '/photos/doctors/dr-g-anjum.jpg', 'Dedicated to providing quality dental care with a focus on oral health, patient comfort, and personalised treatment. Committed to helping patients maintain healthy smiles through preventive and comprehensive dental care.', NULL, 10),
  ('dr-dhanashree-g', 'Dr. Dhanashree G', 'Implantology & Endodontics', 'FBOCI', '5 Years of Clinical Experience', 'Dental Surgeon | Implantology & Endodontics', '/photos/doctors/dr-dhanashree-g.jpg', 'Dr. Dhanashree G is a skilled dental professional with 5 years of clinical experience. She is a Fellow of the Brånemark Osseointegration Center India (FBOCI) and has also completed a fellowship in Conservative Dentistry and Endodontics.\n\nWith specialized training in dental implantology and endodontics, she is committed to providing quality dental care with a focus on precision, patient comfort and long-lasting oral health.', NULL, 11),
  ('dr-masroor', 'Dr. Masroor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12);
